True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    lines = set()
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            lines.update((r, c) for c in range(w))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            lines.update((r, c) for r in range(h))
    for r, c in lines:
        out[r][c] = 2
    return out
